package app.relaydrop;

import android.content.Context;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.util.Base64;
import org.json.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;

/** Remote invitations carry only a join capability and public certificate pins. */
final class RemoteConnections {
  static final String UUID="[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}",SECRET="[A-Za-z0-9_-]{42}[AEIMQUYcgkosw048]",PIN="[a-f0-9]{64}";
  private static final String KEY="relaydrop-remote-config-v1";
  private static final Object LOCK=new Object();
  private final android.content.SharedPreferences prefs;
  RemoteConnections(Context context){prefs=context.getSharedPreferences("remote-connections",Context.MODE_PRIVATE);}
  static String token(){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);return Base64.encodeToString(bytes,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);}
  static URI relay(String raw)throws Exception{if(raw==null||raw.length()>512||raw.matches("(?s).*[\\x00-\\x20\\x7f\\\\].*"))throw new IllegalArgumentException("中继地址无效。");URI u=new URI(raw);if(!"tls".equals(u.getScheme())||u.getHost()==null||!(u.getHost().matches("[A-Za-z0-9.-]{1,253}")||u.getHost().matches("\\[[A-Fa-f0-9:]+\\]"))||u.getRawUserInfo()!=null||u.getRawQuery()!=null||u.getRawFragment()!=null||(u.getRawPath()!=null&&!u.getRawPath().isEmpty())||(u.getPort()!=-1&&u.getPort()<1)||u.getPort()>65535)throw new IllegalArgumentException("请输入 tls://主机名:端口 格式的中继地址。");return u.getPort()==-1?new URI("tls",null,u.getHost(),443,null,null,null):u;}
  static void endpoint(JSONObject value)throws Exception{if(!(value.opt("relay") instanceof String)||!value.has("relayFingerprint"))throw new IllegalArgumentException("中继配置无效。");relay(value.getString("relay"));if(!value.isNull("relayFingerprint")&&(!(value.opt("relayFingerprint") instanceof String)||!value.optString("relayFingerprint").matches(PIN)))throw new IllegalArgumentException("中继证书指纹须为完整的 64 位 SHA-256。");}
  static JSONObject invitation(String text)throws Exception{
    if(text==null||text.length()>4096||!text.startsWith("relaydrop-remote://v1/"))throw new IllegalArgumentException("请输入完整远程邀请。");String raw=text.substring("relaydrop-remote://v1/".length());if(!raw.matches("[A-Za-z0-9_-]+"))throw new IllegalArgumentException("邀请格式无效。");byte[] decoded=Base64.decode(raw,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);if(!Base64.encodeToString(decoded,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING).equals(raw))throw new IllegalArgumentException("邀请编码无效。");
    JSONTokener parser=new JSONTokener(new String(decoded,StandardCharsets.UTF_8));Object parsed=parser.nextValue();if(!(parsed instanceof JSONObject)||parser.nextClean()!=0)throw new IllegalArgumentException("邀请内容无效。");JSONObject value=(JSONObject)parsed;String[] fields={"v","relay","relayFingerprint","room","serverId","joinKey","fingerprint"};if(value.length()!=fields.length)throw new IllegalArgumentException("邀请字段无效。");for(String field:fields)if(!value.has(field))throw new IllegalArgumentException("邀请字段不完整。");for(String field:new String[]{"relay","room","serverId","joinKey","fingerprint"})if(!(value.opt(field) instanceof String))throw new IllegalArgumentException("邀请字段类型无效。");if(!(value.opt("v") instanceof Number)||((Number)value.get("v")).doubleValue()!=1||!value.getString("room").matches(UUID)||!value.getString("serverId").equals(value.getString("room"))||!value.getString("joinKey").matches(SECRET)||!value.getString("fingerprint").matches(PIN))throw new IllegalArgumentException("邀请身份或权限无效。");endpoint(value);return value;
  }
  static String invitation(JSONObject host,TlsIdentity id)throws Exception{JSONObject v=new JSONObject().put("v",1).put("relay",host.getString("relay")).put("relayFingerprint",host.opt("relayFingerprint")).put("room",id.serverId).put("serverId",id.serverId).put("joinKey",host.getString("joinKey")).put("fingerprint",id.fingerprint);return "relaydrop-remote://v1/"+Base64.encodeToString(v.toString().getBytes(StandardCharsets.UTF_8),Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);}
  private static synchronized SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(store.containsAlias(KEY))return (SecretKey)store.getKey(KEY,null);KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(KEY,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return g.generateKey();}
  private JSONObject load()throws Exception{String raw=prefs.getString("encrypted",null);if(raw==null)return new JSONObject().put("profiles",new JSONArray());String[] pair=raw.split(":",2);if(pair.length!=2)throw new java.io.IOException("远程配置损坏，未自动重置。");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(pair[0],Base64.NO_WRAP)));c.updateAAD(KEY.getBytes(StandardCharsets.UTF_8));return new JSONObject(new String(c.doFinal(Base64.decode(pair[1],Base64.NO_WRAP)),StandardCharsets.UTF_8));}
  private void save(JSONObject value)throws Exception{byte[] bytes=value.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>65536)throw new java.io.IOException("远程配置过大。");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());c.updateAAD(KEY.getBytes(StandardCharsets.UTF_8));String encoded=Base64.encodeToString(c.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(c.doFinal(bytes),Base64.NO_WRAP);if(!prefs.edit().putString("encrypted",encoded).commit())throw new java.io.IOException("远程配置保存失败。");}
  JSONObject host()throws Exception{synchronized(LOCK){return load().optJSONObject("host");}}
  void rotateInvitation()throws Exception{synchronized(LOCK){JSONObject all=load(),h=all.optJSONObject("host");if(h==null)throw new java.io.IOException("尚未配置远程共享。");h.put("joinKey",token());save(all);}}
  void host(String relay,String fingerprint,String serviceKey)throws Exception{synchronized(LOCK){JSONObject all=load(),old=all.optJSONObject("host"),h=new JSONObject().put("relay",relay).put("relayFingerprint",fingerprint.isEmpty()?JSONObject.NULL:fingerprint).put("serviceKey",serviceKey).put("hostKey",old==null?token():old.getString("hostKey")).put("joinKey",old==null?token():old.getString("joinKey"));endpoint(h);if(!serviceKey.matches(SECRET))throw new IllegalArgumentException("服务密钥须为服务器提供的 43 位密钥。");all.put("host",h);save(all);}}
  JSONArray profiles()throws Exception{synchronized(LOCK){return load().getJSONArray("profiles");}}
  JSONObject profile(String id)throws Exception{JSONArray a=profiles();for(int i=0;i<a.length();i++)if(id.equals(a.getJSONObject(i).getJSONObject("invite").getString("serverId")))return a.getJSONObject(i);return null;}
  JSONObject atOrigin(String origin)throws Exception{JSONArray a=profiles();for(int i=0;i<a.length();i++)if(origin.equals("https://127.0.0.1:"+a.getJSONObject(i).getInt("port")))return a.getJSONObject(i);return null;}
  void put(JSONObject invite,int port)throws Exception{synchronized(LOCK){JSONObject all=load();JSONArray a=all.getJSONArray("profiles"),next=new JSONArray();for(int i=0;i<a.length();i++){JSONObject p=a.getJSONObject(i);if(p.getJSONObject("invite").getString("serverId").equals(invite.getString("serverId"))){if(!p.getJSONObject("invite").getString("fingerprint").equals(invite.getString("fingerprint")))throw new java.io.IOException("设备证书变化，请先移除旧远程设备并重新核对。");}else{if(p.getInt("port")==port)throw new java.io.IOException("远程本地端口已被其他身份占用。");next.put(p);}}if(next.length()>=10)throw new java.io.IOException("最多保存 10 台远程设备。");next.put(new JSONObject().put("invite",invite).put("port",port));all.put("profiles",next);save(all);}}
  void remove(String id)throws Exception{synchronized(LOCK){JSONObject all=load();JSONArray a=all.getJSONArray("profiles"),next=new JSONArray();for(int i=0;i<a.length();i++)if(!id.equals(a.getJSONObject(i).getJSONObject("invite").getString("serverId")))next.put(a.getJSONObject(i));all.put("profiles",next);save(all);}}
}
